class Solution {
public:
    int cherryPickup(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<vector<int>> dp(n, vector<int>(n, -1));
        dp[0][0] = grid[0][0];

        for (int k = 1; k <= 2 * n - 2; ++k) {
            vector<vector<int>> next_dp(n, vector<int>(n, -1));
            for (int r1 = 0; r1 < n; ++r1) {
                for (int r2 = 0; r2 < n; ++r2) {
                    int c1 = k - r1;
                    int c2 = k - r2;
                    if (c1 < 0 || c1 >= n || c2 < 0 || c2 >= n) continue;
                    if (grid[r1][c1] == -1 || grid[r2][c2] == -1) continue;

                    int max_prev = -1;
                    if (r1 > 0 && r2 > 0) max_prev = max(max_prev, dp[r1-1][r2-1]);
                    if (r1 > 0) max_prev = max(max_prev, dp[r1-1][r2]);
                    if (r2 > 0) max_prev = max(max_prev, dp[r1][r2-1]);
                    max_prev = max(max_prev, dp[r1][r2]);

                    if (max_prev == -1) continue;

                    if (r1 == r2) {
                        next_dp[r1][r2] = max_prev + grid[r1][c1];
                    } else {
                        next_dp[r1][r2] = max_prev + grid[r1][c1] + grid[r2][c2];
                    }
                }
            }
            dp = next_dp;
        }
        return max(0, dp[n-1][n-1]);
    }
};
